+}
+
+.product-card__meta,
+.deal-card__meta {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  margin-top: 1rem;
+}
+
+.product-card__price {
+  font-weight: 700;
+}
+
+.deal-card__value {
+  font-weight: 700;
+  color: var(--accent-warm);
+}
+
+.promo-band {
+  margin-top: 3.5rem;
+  padding: 1.4rem 1.5rem;
+  border-radius: var(--radius-xl);
